rows = frappe.get_list("Check In", fields=["name", "checked_in_at", "attendee"], limit_page_length=0)
groups = {}
att = set()
for r in rows:
    t = frappe.utils.get_datetime(r.checked_in_at)
    slot = "%02d:%02d" % (t.hour, 0 if t.minute < 30 else 30)
    groups.setdefault(slot, []).append(r.name)
    att.add(r.attendee)
counts = {}
for slot in sorted(groups):
    names = groups[slot]
    for i in range(0, len(names), 200):
        update("Check In", names[i:i+200], {"slot": slot})
    counts[slot] = len(names)
alist = sorted(att)
for i in range(0, len(alist), 200):
    update("Attendee", alist[i:i+200], {"checked_in": 1})
result = {"slots": counts, "checked_in_attendees": len(alist)}
